  subscribe(tenantId, cb) { this.subs.set(tenantId, cb); }
  unsubscribe(tenantId) { this.subs.delete(tenantId); }
  _onMessage(e) { const m = JSON.parse(e.data); if (this.subs.has(m.tenantId)) this.subs.get(m.tenantId)(m); }
}
